        },
        {
          "@type": "Question",
          "name": "Is pickup free?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Pickup is available at no charge for qualifying volumes. Equipment types, quantities, loading access, and service requirements affect eligibility, so STS reviews each project before confirming pickup arrangements."
